import type { NextConfig } from "next";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

// Served under this prefix on nicholaswood.com.au. The app uses hash routing
// inside the page, so the prefix is the only path the server needs to own.
export const BASE_PATH = "/lsv/dailysummary";

let version = "dev";
try {
  const manifest = JSON.parse(readFileSync(resolve(__dirname, ".release-please-manifest.json"), "utf8"));
  version = manifest["."] ?? "dev";
} catch {
  // manifest absent in some environments
}

const nextConfig: NextConfig = {
  output: "standalone",
  basePath: BASE_PATH,
  poweredByHeader: false,
  env: {
    NEXT_PUBLIC_APP_VERSION: version,
    NEXT_PUBLIC_BASE_PATH: BASE_PATH,
  },
  // Static headers for everything except the OSS page itself, which sets a
  // per-request nonce CSP in its route handler (see src/app/route.ts).
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
          { key: "Strict-Transport-Security", value: "max-age=31536000; includeSubDomains" },
        ],
      },
    ];
  },
};

export default nextConfig;

import { z } from "zod";

/**
 * Server environment, validated lazily so build steps that do not need
 * secrets still succeed. Mirrors AccessBuddy's apps/web/src/env.ts shape.
 */
const serverSchema = z.object({
  SESSION_SIGNING_SECRET: z.string().min(32).optional(),
  RESEND_API_KEY: z.string().optional(),
  RESEND_FROM: z.string().optional(),
  CRON_INVOKER_EMAIL: z.string().email().optional(),
  ENABLE_DEV_LOGIN: z.enum(["true", "false"]).optional(),
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
});

let _server: z.infer<typeof serverSchema> | null = null;
export function serverEnv() {
  if (_server) return _server;
  const parsed = serverSchema.safeParse(process.env);
  if (!parsed.success) {
    throw new Error(`Invalid server environment: ${parsed.error.message}`);
  }
  _server = parsed.data;
  return _server;
}

export const clientEnv = {
  NEXT_PUBLIC_APP_URL: process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000",
  NEXT_PUBLIC_FIREBASE_API_KEY: process.env.NEXT_PUBLIC_FIREBASE_API_KEY ?? "",
  NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN ?? "",
  NEXT_PUBLIC_FIREBASE_PROJECT_ID: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? "",
  NEXT_PUBLIC_FIREBASE_APP_ID: process.env.NEXT_PUBLIC_FIREBASE_APP_ID ?? "",
  NEXT_PUBLIC_BASE_PATH: process.env.NEXT_PUBLIC_BASE_PATH ?? "/lsv/dailysummary",
  NEXT_PUBLIC_APP_VERSION: process.env.NEXT_PUBLIC_APP_VERSION ?? "dev",
};

const MIN_SESSION_SIGNING_SECRET_LENGTH = 32;

/**
 * Dedicated session-signing secret. Throws when unset or too short so OTP
 * sessions fail closed instead of being signed with a guessable value.
 * Copied from AccessBuddy's getSessionSigningSecret().
 */
export function getSessionSigningSecret(): string {
  const secret = process.env.SESSION_SIGNING_SECRET;
  if (!secret || secret.length < MIN_SESSION_SIGNING_SECRET_LENGTH) {
    throw new Error(
      `SESSION_SIGNING_SECRET is required and must be at least ${MIN_SESSION_SIGNING_SECRET_LENGTH} characters. ` +
        "Refusing to sign or verify session cookies without it."
    );
  }
  return secret;
}

/** Email sending through Resend is on only when both values are configured. */
export function resendConfigured(): boolean {
  return !!process.env.RESEND_API_KEY && !!process.env.RESEND_FROM;
}

import { initializeApp, getApps, cert, applicationDefault, type App } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { getFirestore, type Firestore } from "firebase-admin/firestore";

let adminApp: App | null = null;

function getAdminApp(): App {
  if (adminApp) return adminApp;
  if (getApps().length > 0) {
    adminApp = getApps()[0];
    return adminApp;
  }
  const projectId = process.env.FIREBASE_PROJECT_ID ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
  if (process.env.FIREBASE_SERVICE_ACCOUNT_KEY) {
    adminApp = initializeApp({ credential: cert(JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT_KEY)), projectId });
  } else {
    // Cloud Run: Application Default Credentials from the runtime service
    // account. Locally: GOOGLE_APPLICATION_CREDENTIALS or gcloud ADC.
    adminApp = initializeApp({ credential: applicationDefault(), projectId });
  }
  return adminApp;
}

export function getAdminAuth() {
  return getAuth(getAdminApp());
}

let _db: Firestore | null = null;
export function adminDb(): Firestore {
  if (_db) return _db;
  _db = getFirestore(getAdminApp());
  return _db;
}

import { FieldValue } from "firebase-admin/firestore";
import { adminDb, getAdminAuth } from "./firebase-admin";

/**
 * The member allow-list. One doc per member, keyed by lower-cased email, in
 * the `members` collection. Plays the role AccessBuddy's tenant_memberships
 * and admin_assignments rows play: only listed emails can hold a session,
 * and only admins can edit the list.
 */
export type MemberRecord = {
  email: string;
  displayName: string;
  role: "member" | "admin";
  uid?: string;
  addedBy: string;
  addedAt: string;
  lastSignInAt?: string;
};

export function normaliseEmail(email: string): string {
  return email.toLowerCase().trim();
}

export async function getMemberByEmail(email: string): Promise<MemberRecord | null> {
  const snap = await adminDb().collection("members").doc(normaliseEmail(email)).get();
  return snap.exists ? (snap.data() as MemberRecord) : null;
}

export async function listMembers(): Promise<MemberRecord[]> {
  const snap = await adminDb().collection("members").orderBy("displayName").get();
  return snap.docs.map((d) => d.data() as MemberRecord);
}

export async function upsertMember(
  input: Pick<MemberRecord, "email" | "displayName" | "role">,
  actorEmail: string
): Promise<MemberRecord> {
  const email = normaliseEmail(input.email);
  const ref = adminDb().collection("members").doc(email);
  const existing = await ref.get();
  const record: MemberRecord = {
    email,
    displayName: input.displayName.trim(),
    role: input.role,
    addedBy: existing.exists ? (existing.data() as MemberRecord).addedBy : actorEmail,
    addedAt: existing.exists ? (existing.data() as MemberRecord).addedAt : new Date().toISOString(),
    ...(existing.exists && (existing.data() as MemberRecord).uid ? { uid: (existing.data() as MemberRecord).uid } : {}),
  };
  await ref.set(record, { merge: true });
  // Keep the Firebase custom claim in step so a role change reaches rules on
  // the next token refresh.
  if (record.uid) await syncClaims(record.uid, record);
  return record;
}

export async function removeMember(email: string): Promise<void> {
  const ref = adminDb().collection("members").doc(normaliseEmail(email));
  const snap = await ref.get();
  if (!snap.exists) return;
  const rec = snap.data() as MemberRecord;
  await ref.delete();
  if (rec.uid) {
    const auth = getAdminAuth();
    await auth.setCustomUserClaims(rec.uid, { member: false, admin: false });
    // Invalidates refresh tokens so the browser Firestore session dies too.
    await auth.revokeRefreshTokens(rec.uid);
  }
}

/** Record the Firebase uid against the member and set the rules claims. */
export async function linkMemberUid(email: string, uid: string): Promise<MemberRecord | null> {
  const ref = adminDb().collection("members").doc(normaliseEmail(email));
  const snap = await ref.get();
  if (!snap.exists) return null;
  const rec = snap.data() as MemberRecord;
  await ref.set({ uid, lastSignInAt: FieldValue.serverTimestamp() }, { merge: true });
  await syncClaims(uid, rec);
  return { ...rec, uid };
}

async function syncClaims(uid: string, rec: MemberRecord): Promise<void> {
  await getAdminAuth().setCustomUserClaims(uid, {
    member: true,
    admin: rec.role === "admin",
    name: rec.displayName,
  });
}

/**
 * Only accepts a same-origin, root-relative path for post-sign-in redirects.
 * Rejects off-origin, protocol-relative and backslash forms. Copied from
 * AccessBuddy's lib/safe-redirect.ts.
 */
export function safeRedirect(value: string | null | undefined, fallback = "/"): string {
  if (!value) return fallback;
  if (!value.startsWith("/")) return fallback;
  if (value.startsWith("//")) return fallback;
  if (value.includes("\\")) return fallback;
  return value;
}

import { createHmac, timingSafeEqual } from "node:crypto";
import { getSessionSigningSecret } from "@/env";
import { getAdminAuth } from "./firebase-admin";
import { getMemberByEmail, type MemberRecord } from "./members";

export const SESSION_COOKIE_NAME = "session";
/** 14 days, the same lifetime AccessBuddy uses. */
export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 14;

export const sessionCookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "lax" as const,
  path: "/",
  maxAge: SESSION_MAX_AGE_SECONDS,
};

type OtpSessionPayload = { uid: string; email: string; iat: number; exp: number; webauthn: true };

/**
 * Sign an OTP session with SESSION_SIGNING_SECRET. Same `webauthn.<b64>.<sig>`
 * shape AccessBuddy issues for OTP and passkey sign-ins, so the verifier is
 * byte-compatible.
 */
export function signOtpSession(payload: Pick<OtpSessionPayload, "uid" | "email">): string {
  const now = Math.floor(Date.now() / 1000);
  const full: OtpSessionPayload = { uid: payload.uid, email: payload.email, iat: now, exp: now + SESSION_MAX_AGE_SECONDS, webauthn: true };
  const payloadStr = JSON.stringify(full);
  const sig = createHmac("sha256", getSessionSigningSecret()).update(payloadStr).digest("base64url");
  return `webauthn.${Buffer.from(payloadStr).toString("base64url")}.${sig}`;
}

export function verifyOtpSessionCookie(value: string): { uid: string; email: string } | null {
  const parts = value.split(".");
  if (parts.length !== 3 || parts[0] !== "webauthn") return null;
  const payloadStr = Buffer.from(parts[1], "base64url").toString();
  let payload: Record<string, unknown>;
  try {
    payload = JSON.parse(payloadStr);
  } catch {
    return null;
  }
  const expected = createHmac("sha256", getSessionSigningSecret()).update(payloadStr).digest("base64url");
  const provided = parts[2];
  if (provided.length !== expected.length || !timingSafeEqual(Buffer.from(provided), Buffer.from(expected))) return null;
  const exp = typeof payload.exp === "number" ? payload.exp : null;
  if (!exp || exp < Math.floor(Date.now() / 1000)) return null;
  const uid = typeof payload.uid === "string" ? payload.uid : "";
  if (!uid) return null;
  const email = typeof payload.email === "string" ? payload.email.toLowerCase().trim() : "";
  return { uid, email };
}

export type AuthUser = { uid: string; email: string; displayName: string; role: "member" | "admin" };

/**
 * Resolve the signed-in member from the `session` cookie, or null.
 * Firebase session cookies are verified with revocation checking; OTP
 * cookies with the HMAC verifier. In both cases the email must still be on
 * the allow-list: removing a member takes effect on their next request.
 */
export async function getAuthUserFromCookie(cookieValue: string | undefined): Promise<AuthUser | null> {
  if (!cookieValue) return null;
  try {
    let uid: string;
    let email: string;
    if (cookieValue.startsWith("webauthn.")) {
      const v = verifyOtpSessionCookie(cookieValue);
      if (!v) return null;
      uid = v.uid;
      email = v.email;
    } else {
      const decoded = await getAdminAuth().verifySessionCookie(cookieValue, true);
      uid = decoded.uid;
      email = (decoded.email ?? "").toLowerCase().trim();
    }
    if (!uid || !email) return null;
    const member = await getMemberByEmail(email);
    if (!member) return null;
    return toAuthUser(uid, member);
  } catch (err) {
    console.error("Session verification failed:", err);
    return null;
  }
}

export function toAuthUser(uid: string, member: MemberRecord): AuthUser {
  return { uid, email: member.email, displayName: member.displayName || member.email, role: member.role };
}

/** Next.js request-context helper. */
export async function getAuthUser(): Promise<AuthUser | null> {
  try {
    const { cookies } = await import("next/headers");
    const store = await cookies();
    return getAuthUserFromCookie(store.get(SESSION_COOKIE_NAME)?.value);
  } catch {
    return null;
  }
}

export function firstName(displayName: string): string {
  return displayName.trim().split(/\s+/)[0] ?? "";
}

import { adminDb } from "./firebase-admin";

/**
 * Fixed-window rate limiter on Firestore (`rateLimitBuckets`), the Firestore
 * twin of AccessBuddy's Postgres `rate_limit_buckets`. One transaction per
 * check keeps the counter consistent across Cloud Run instances.
 * Kill switch: RATE_LIMIT_DISABLED=1.
 */
export function getClientIp(request: Request): string {
  const fwd = request.headers.get("x-forwarded-for");
  if (fwd) {
    const first = fwd.split(",")[0]?.trim();
    if (first) return first;
  }
  const real = request.headers.get("x-real-ip");
  if (real) return real.trim();
  return "unknown";
}

export type RateLimitResult = { ok: boolean; remaining: number; retryAfter: number };
export type RateLimitOptions = { namespace: string; windowSeconds: number; max: number };

export async function checkRateLimit(key: string, options: RateLimitOptions): Promise<RateLimitResult> {
  if (process.env.RATE_LIMIT_DISABLED === "1") return { ok: true, remaining: options.max, retryAfter: 0 };
  const docId = encodeURIComponent(`${options.namespace}:${key}`);
  const ref = adminDb().collection("rateLimitBuckets").doc(docId);
  const now = Date.now();
  const windowMs = options.windowSeconds * 1000;
  const result = await adminDb().runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const data = snap.exists ? (snap.data() as { count: number; resetAt: number }) : null;
    if (!data || data.resetAt <= now) {
      tx.set(ref, { count: 1, resetAt: now + windowMs });
      return { count: 1, resetAt: now + windowMs };
    }
    tx.update(ref, { count: data.count + 1 });
    return { count: data.count + 1, resetAt: data.resetAt };
  });
  if (result.count > options.max) {
    return { ok: false, remaining: 0, retryAfter: Math.max(1, Math.ceil((result.resetAt - now) / 1000)) };
  }
  return { ok: true, remaining: Math.max(0, options.max - result.count), retryAfter: 0 };
}

export async function checkRateLimitIpAndEmail(
  namespace: string,
  ip: string,
  email: string,
  options: { windowSeconds: number; maxPerIp: number; maxPerEmail: number }
): Promise<RateLimitResult> {
  const ipResult = await checkRateLimit(`ip:${ip}`, { namespace, windowSeconds: options.windowSeconds, max: options.maxPerIp });
  if (!ipResult.ok) return ipResult;
  return checkRateLimit(`email:${email}`, { namespace, windowSeconds: options.windowSeconds, max: options.maxPerEmail });
}

import { randomBytes, randomInt, scryptSync, timingSafeEqual } from "node:crypto";
import { adminDb } from "./firebase-admin";

/**
 * Hashed, single-use, attempt-capped OTP store on Firestore (`otpCodes`),
 * mirroring AccessBuddy's Postgres otp-store. Codes come from
 * crypto.randomInt rather than Math.random.
 */
const OTP_TTL_MS = 5 * 60 * 1000;
const MAX_ATTEMPTS = 5;
const SCRYPT_KEYLEN = 64;

export type VerifyOtpResult = "valid" | "invalid" | "expired" | "locked";

function hashCode(code: string, salt: string): string {
  return scryptSync(code, salt, SCRYPT_KEYLEN).toString("hex");
}

export function generateOtpCode(): string {
  return String(randomInt(0, 1_000_000)).padStart(6, "0");
}

export async function setOtp(email: string, code: string): Promise<void> {
  const salt = randomBytes(16).toString("hex");
  await adminDb().collection("otpCodes").doc(email).set({
    codeHash: `${salt}:${hashCode(code, salt)}`,
    expiresAt: Date.now() + OTP_TTL_MS,
    attempts: 0,
    consumedAt: null,
  });
}

export async function verifyOtp(email: string, code: string): Promise<VerifyOtpResult> {
  const ref = adminDb().collection("otpCodes").doc(email);
  return adminDb().runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    if (!snap.exists) return "invalid";
    const e = snap.data() as { codeHash: string; expiresAt: number; attempts: number; consumedAt: number | null };
    if (e.consumedAt) return "invalid";
    if (e.expiresAt < Date.now()) return "expired";
    if (e.attempts >= MAX_ATTEMPTS) return "locked";
    const [salt, stored] = e.codeHash.split(":");
    const candidate = hashCode(code, salt);
    const matches = stored.length === candidate.length && timingSafeEqual(Buffer.from(stored, "hex"), Buffer.from(candidate, "hex"));
    if (!matches) {
      tx.update(ref, { attempts: e.attempts + 1 });
      return "invalid";
    }
    tx.update(ref, { consumedAt: Date.now() });
    return "valid";
  });
}

import { Resend } from "resend";
import { resendConfigured } from "@/env";

/**
 * Transactional email through Resend, the provider AccessBuddy uses. Only
 * active when RESEND_API_KEY and RESEND_FROM are set; otherwise callers fall
 * back to Firebase's own magic-link mailer and hide the code option.
 */
let _resend: Resend | null = null;
function getResend(): Resend | null {
  if (!resendConfigured()) return null;
  if (!_resend) _resend = new Resend(process.env.RESEND_API_KEY);
  return _resend;
}

export type EmailSendResult = { sent: boolean; error?: string };

async function send(to: string, subject: string, html: string, text: string): Promise<EmailSendResult> {
  const resend = getResend();
  if (!resend) return { sent: false, error: "Email provider not configured" };
  const result = await resend.emails.send({ from: process.env.RESEND_FROM!, to, subject, html, text });
  if (result.error) return { sent: false, error: result.error.message };
  return { sent: true };
}

export function sendMagicLinkEmail(to: string, link: string): Promise<EmailSendResult> {
  const text = `Sign in to the LSV Operational Service Summary:\n\n${link}\n\nThe link expires shortly and can be used once. If you did not request it, ignore this email.`;
  const html = `<p>Sign in to the LSV Operational Service Summary:</p><p><a href="${link}">Sign in</a></p><p style="color:#666;font-size:12px">The link expires shortly and can be used once. If you did not request it, ignore this email.</p>`;
  return send(to, "Your sign-in link", html, text);
}

export function sendVerificationCodeEmail(to: string, code: string): Promise<EmailSendResult> {
  const text = `Your LSV Operational Service Summary sign-in code is ${code}. It expires in 5 minutes.`;
  const html = `<p>Your sign-in code is</p><p style="font-size:28px;letter-spacing:0.3em;font-family:monospace">${code}</p><p style="color:#666;font-size:12px">It expires in 5 minutes.</p>`;
  return send(to, "Your sign-in code", html, text);
}

import { NextResponse } from "next/server";
import { OAuth2Client } from "google-auth-library";
import { clientEnv, serverEnv } from "@/env";

const client = new OAuth2Client();

/**
 * Cloud Scheduler calls the weather route with a Google-signed OIDC token
 * (audience = the route URL, email = the scheduler service account). This
 * verifies that token instead of AccessBuddy's shared x-cron-secret header,
 * so no secret sits in Terraform state or the job definition. Fails closed
 * when CRON_INVOKER_EMAIL is unset (503).
 */
export async function requireScheduler(request: Request, routeName: string): Promise<NextResponse | null> {
  const expectedEmail = serverEnv().CRON_INVOKER_EMAIL;
  if (!expectedEmail) {
    console.error(`Cron ${routeName} invoked but CRON_INVOKER_EMAIL is not configured`);
    return NextResponse.json({ error: "Service misconfigured" }, { status: 503 });
  }
  const authz = request.headers.get("authorization") ?? "";
  const token = authz.startsWith("Bearer ") ? authz.slice(7) : "";
  if (!token) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  try {
    const audience = `${clientEnv.NEXT_PUBLIC_APP_URL}${clientEnv.NEXT_PUBLIC_BASE_PATH}/api/cron/${routeName}`;
    const ticket = await client.verifyIdToken({ idToken: token, audience });
    const payload = ticket.getPayload();
    if (!payload?.email_verified || payload.email !== expectedEmail) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    return null;
  } catch (err) {
    console.error(`Cron ${routeName} OIDC verification failed:`, err);
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
}

"use client";

import { initializeApp, getApps } from "firebase/app";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
};

const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
export const auth = getAuth(app);

