// A wind sentence starts the sentence ("Winds northerly..." / "Light winds."),
// not a mid-sentence "winds, large hail and heavy rain" from a storm warning.
const WIND_RE = /(?:^|\.\s+)((?:Light w|W)inds?\b[^.]*\.)/;
